  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', 'cd50b4f5-3efb-44bb-a0db-a18c9bff356a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'What does the story suggest about Mrs Pumphrey's character?'$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"She is cruel to animals."},{"id":"b","text":"She cares deeply for Tricki."},{"id":"c","text":"She lacks knowledge in animal care."},{"id":"d","text":"She prefers cats over dogs."}]$qbx$::jsonb, $qbx$c$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-660Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', 'cd50b4f5-3efb-44bb-a0db-a18c9bff356a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'Why did Mrs Pumphrey almost throw the coats through the window?'$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"She wanted to show her anger at Mr Herriot."},{"id":"b","text":"She was concerned about Tricki's health and needed all his clothes for a hospital stay."},{"id":"c","text":"She thought they were unnecessary clutter in the house."},{"id":"d","text":"She didn't want Tricki to get dirty during the car journey."}]$qbx$::jsonb, $qbx$b$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-660Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
