  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', 'cd50b4f5-3efb-44bb-a0db-a18c9bff356a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'What did Mr Herriot suggest to Mrs Pumphrey?'$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"To keep Tricki at home where he could be watched closely."},{"id":"b","text":"To take Tricki for a walk in the park every day."},{"id":"c","text":"To feed Tricki only sweets and no other food."},{"id":"d","text":"To put Tricki in a hospital for treatment immediately."}]$qbx$::jsonb, $qbx$d$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-660Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', 'cd50b4f5-3efb-44bb-a0db-a18c9bff356a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'Why did Mrs Pumphrey almost faint during her conversation with Mr Herriot?'$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"She was too worried about Tricki's health to be coherent."},{"id":"b","text":"She had realized how much money it would cost to take Tricki to the hospital."},{"id":"c","text":"She felt guilty for not taking better care of Tricki."},{"id":"d","text":"She thought Mr Herriot wanted to take her to court over his advice."}]$qbx$::jsonb, $qbx$a$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-660Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', 'cd50b4f5-3efb-44bb-a0db-a18c9bff356a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'What is Mrs Pumphrey's biggest concern regarding Tricki?'$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"His lack of exercise leads to obesity."},{"id":"b","text":"He might catch a disease due to poor living conditions."},{"id":"c","text":"He may suffer from a psychological condition because of loneliness."},{"id":"d","text":"Tricki might escape and cause trouble for her family."}]$qbx$::jsonb, $qbx$b$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-660Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', 'cd50b4f5-3efb-44bb-a0db-a18c9bff356a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'What did Mr Herriot do when Mrs Pumphrey was unable to change Tricki's habits?'$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"He advised her on home remedies."},{"id":"b","text":"He recommended hospitalization immediately."},{"id":"c","text":"He left the decision up to Mrs Pumphrey to decide."},{"id":"d","text":"He suggested taking Tricki for walks every day as a solution."}]$qbx$::jsonb, $qbx$b$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-660Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', 'cd50b4f5-3efb-44bb-a0db-a18c9bff356a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'What is 'I' referring to when saying 'You haven’t a kick in you but I think I know a cure for you'?$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"Tricki, the narrator of the story."},{"id":"b","text":"Mr Herriot, who has found a solution for Tricki’s condition."},{"id":"c","text":"Mrs Pumphrey, who is worried about her dog's health issues."},{"id":"d","text":"The reader, who can provide solutions to animal ailments."}]$qbx$::jsonb, $qbx$b$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-660Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', 'cd50b4f5-3efb-44bb-a0db-a18c9bff356a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'What does the author suggest Mrs Pumphrey should do to help Tricki?'$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"Cut down on food and increase exercise immediately."},{"id":"b","text":"Give him more sweets and treats to encourage eating."},{"id":"c","text":"Keep his room as it is, clean and tidy."},{"id":"d","text":"Take Tricki for walks every day in the park."}]$qbx$::jsonb, $qbx$a$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-660Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', 'cd50b4f5-3efb-44bb-a0db-a18c9bff356a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'What does 'I' mean when saying Tricki had bouts of vomiting?'$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"Tricki’s vomit was red and he needed immediate medical attention."},{"id":"b","text":"He had no appetite for food, only for vomit."},{"id":"c","text":"Tricki would sometimes throw up after eating something."},{"id":"d","text":"Mr Herriot saw Tricki throwing up in his face during the car journey."}]$qbx$::jsonb, $qbx$c$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-660Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', 'cd50b4f5-3efb-44bb-a0db-a18c9bff356a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'What did Mr Herriot think of Mrs Pumphrey's attempts to help Tricki?'$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"He thought she was trying too hard and hurting Tricki with her actions."},{"id":"b","text":"He agreed with her that Tricki needed more exercise."},{"id":"c","text":"He believed that cutting down on food would be harmful to Tricki’s health."},{"id":"d","text":"He advised Mrs Pumphrey to keep increasing Tricki's food intake until he got better."}]$qbx$::jsonb, $qbx$a$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-660Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', 'cd50b4f5-3efb-44bb-a0db-a18c9bff356a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'What was the main reason for Mr Herriot suggesting hospitalization?'$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"Tricki needed a new coat to be put in the hospital bed."},{"id":"b","text":"Mrs Pumphrey insisted on keeping Tricki at home to avoid him getting sick again."},{"id":"c","text":"Mr Herriot thought it was best practice and could provide better care than at home."},{"id":"d","text":"Tricki wanted to go see his dog friends in the hospital."}]$qbx$::jsonb, $qbx$c$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-660Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', 'cd50b4f5-3efb-44bb-a0db-a18c9bff356a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'What did Mr Herriot think would be the outcome if Mrs Pumphrey didn't take Tricki's condition seriously?'$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"Tricki might get a new coat from the charity shop."},{"id":"b","text":"Mrs Pumphrey would feel guilty for not taking better care of her pet dog."},{"id":"c","text":"Tricki could die or become severely ill if he wasn't hospitalized soon enough."},{"id":"d","text":"Mr Herriot thought Tricki might just get used to his condition and stop eating food altogether."}]$qbx$::jsonb, $qbx$c$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-660Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', 'cd50b4f5-3efb-44bb-a0db-a18c9bff356a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'What does the story suggest about human-animal relationships?'$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"It is only important for humans to care for their own kind, not animals."},{"id":"b","text":"Humans should always be responsible for their pets' health and needs."},{"id":"c","text":"Animals are more resilient than humans and can handle any situation alone."},{"id":"d","text":"Pets often make us question our priorities and the lengths we go to ensure they are cared for."}]$qbx$::jsonb, $qbx$d$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-660Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', 'cd50b4f5-3efb-44bb-a0db-a18c9bff356a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'What does Tricki's story tell about Mrs Pumphrey’s character?'$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"She is irresponsible but loving towards her dog."},{"id":"b","text":"She loves her dog more than she cares for his health needs."},{"id":"c","text":"She lacks understanding of animal nutrition and exercise routines."},{"id":"d","text":"She only looks after Tricki when he isn't causing any trouble in the house."}]$qbx$::jsonb, $qbx$b$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-660Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', 'cd50b4f5-3efb-44bb-a0db-a18c9bff356a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'What does the story suggest about Tricki's personality?'$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"He is very healthy and loves to eat all day long."},{"id":"b","text":"Tricki prefers to be lazy and only eats when he feels like it."},{"id":"c","text":"He enjoys eating food and has a strong appetite at any time of the day or night."},{"id":"d","text":"Tricki is an indoor dog who doesn’t enjoy going out for walks."}]$qbx$::jsonb, $qbx$c$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-660Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', 'cd50b4f5-3efb-44bb-a0db-a18c9bff356a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'What did Mr Herriot find when he arrived at Mrs Pumphrey's house?'$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"A clean and well-organized room, ready for Tricki’s hospital stay."},{"id":"b","text":"Tricki was already in the car with his new owners."},{"id":"c","text":"Mrs Pumphrey had not prepared any clothes or food for Tricki's journey to the hospital."},{"id":"d","text":"He saw Mrs Pumphrey looking at a list of dog breeds and choosing one that might suit her pet better."}]$qbx$::jsonb, $qbx$c$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-660Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', 'cd50b4f5-3efb-44bb-a0db-a18c9bff356a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'What does the story suggest about Mr Herriot’s advice?'$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"It was only given to make Tricki look bad in front of Mrs Pumphrey."},{"id":"b","text":"Mr Herriot's advice was based on his knowledge and experience, even though Mrs Pumphrey refused it at first."},{"id":"c","text":"Mrs Pumphrey ignored Mr Herriot’s advice as she thought he didn’t know what he was talking about."},{"id":"d","text":"Tricki had a severe disease that required immediate attention from a professional vet only."}]$qbx$::jsonb, $qbx$b$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-660Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', 'cd50b4f5-3efb-44bb-a0db-a18c9bff356a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'What does the story imply about human-animal relationships?'$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"Humans can be more irresponsible and neglectful of their pets' needs than animals are towards humans."},{"id":"b","text":"Pets often make us question our priorities and ensure we take better care of them because they require it."},{"id":"c","text":"It is only important for humans to care for their own kind, not animals."},{"id":"d","text":"Animals are more resilient than humans and can handle any situation alone."}]$qbx$::jsonb, $qbx$b$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-660Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
