  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', 'cd50b4f5-3efb-44bb-a0db-a18c9bff356a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$Tricki trotted out and was immediately __________ by Joe, the greyhound, and his friends. After rolling him over and thoroughly inspecting him, the dogs moved off down the garden.$qbx$, 'fill_blank'::question_type, NULL, $qbx$engulfed$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-660Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
